update.foreach:
UPDATE address
userId = #{item.userId}, addressId = #{item.addressId}, country = #{item.country}, province = #{item.province}, city = #{item.city}, county = #{item.county}, detail = #{item.detail}, createTime = #{item.createTime}, `delete` = #{item.delete},
WHERE id = #{item.id}

mapper.select:
SELECT id, userId, addressId, country, province, city, county, detail, createTime, `delete`
FROM address

    AND id = #{entity.id}
    AND userId = #{entity.userId}
    AND addressId = #{entity.addressId}
    AND country = #{entity.country}
    AND province = #{entity.province}
    AND city = #{entity.city}
    AND county = #{entity.county}
    AND detail = #{entity.detail}
    AND createTime = #{entity.createTime}
    AND `delete` = #{entity.delete}
